package com.example.demo;

import java.time.Instant;
import java.util.EnumMap;
import java.util.List;
import org.springframework.stereotype.Service;

@Service
public class SentimentDigestService {
    private final DigestMailService mail;

    public SentimentDigestService(DigestMailService mail) {
        this.mail = mail;
    }

    public String send(String userId, String recipient, boolean optedIn,
            List<Entry> entries, Instant start, Instant end) {
        if (!start.isBefore(end)) {
            throw new IllegalArgumentException("Start must precede end");
        }
        if (!optedIn) return "Digest disabled";

        var counts = new EnumMap<Sentiment, Long>(Sentiment.class);
        for (Entry entry : entries) {
            if (userId.equals(entry.userId())
                    && !entry.createdAt().isBefore(start)
                    && entry.createdAt().isBefore(end)
                    && entry.sentiment() != null) {
                counts.merge(entry.sentiment(), 1L, Long::sum);
            }
        }
        String summary = counts.isEmpty()
                ? "No labeled entries found"
                : counts.toString();
        mail.send(recipient, summary);
        return summary;
    }

    public enum Sentiment { HAPPY, SAD, ANGRY }
    public record Entry(String userId, Instant createdAt, Sentiment sentiment) {}
}

package com.example.demo;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.stereotype.Service;

@Service
public class DigestMailService {
    private final JavaMailSender sender;
    private final String from;

    public DigestMailService(JavaMailSender sender,
            @Value("${app.mail.from}") String from) {
        this.sender = sender;
        this.from = from;
    }

    public void send(String recipient, String summary) {
        var message = new SimpleMailMessage();
        message.setFrom(from);
        message.setTo(recipient);
        message.setSubject("Your weekly journal summary");
        message.setText(summary);
        sender.send(message);
    }
}

